// ─── File: src/test/java/com/bank/utils/CollectionsUtilTest.java ───
package com.bank.utils;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class CollectionsUtilTest {

    @Test
    void sort_naturalAndCustomOrder() {
        List<String> accounts = new ArrayList<>(List.of("CUR3001", "SAV2001", "FD4001"));
        Collections.sort(accounts);
        assertThat(accounts).containsExactly("CUR3001", "FD4001", "SAV2001");

        Collections.sort(accounts, Comparator.reverseOrder());
        assertThat(accounts).containsExactly("SAV2001", "FD4001", "CUR3001");
    }

    @Test
    void binarySearch_afterSort() {
        List<Integer> balances = new ArrayList<>(List.of(10000, 50000, 75000, 120000));
        // Already sorted!
        int idx = Collections.binarySearch(balances, 75000);
        assertThat(idx).isEqualTo(2);  // found at index 2

        int notFound = Collections.binarySearch(balances, 99999);
        assertThat(notFound).isNegative();  // negative = not found (insertion point)
    }

    @Test
    void minMaxFrequency() {
        List<BigDecimal> balances = List.of(
            new BigDecimal("10000"), new BigDecimal("75000"), new BigDecimal("120000"));

        assertThat(Collections.max(balances)).isEqualByComparingTo("120000");
        assertThat(Collections.min(balances)).isEqualByComparingTo("10000");

        List<String> txnTypes = List.of("DEBIT", "CREDIT", "DEBIT", "DEBIT", "CREDIT");
        assertThat(Collections.frequency(txnTypes, "DEBIT")).isEqualTo(3);
        assertThat(Collections.frequency(txnTypes, "CREDIT")).isEqualTo(2);
    }

    @Test
    void reverseShuffleSwap() {
        List<String> list = new ArrayList<>(List.of("A", "B", "C", "D"));

        Collections.reverse(list);
        assertThat(list).containsExactly("D", "C", "B", "A");

        Collections.swap(list, 0, 3);
        assertThat(list).containsExactly("A", "C", "B", "D");

        // Shuffle: random order (can't assert exact order)
        Collections.shuffle(list);
        assertThat(list).containsExactlyInAnyOrder("A", "B", "C", "D");
    }

    @Test
    void unmodifiableList_rejectsModification() {
        List<String> original = new ArrayList<>(List.of("SAV2001"));
        List<String> readOnly = Collections.unmodifiableList(original);

        assertThat(readOnly.get(0)).isEqualTo("SAV2001");
        assertThatThrownBy(() -> readOnly.add("CUR3001"))
            .isInstanceOf(UnsupportedOperationException.class);

        // BUT: modifying original STILL reflects in readOnly (it's a VIEW)!
        original.add("CUR3001");
        assertThat(readOnly).hasSize(2);  // readOnly sees the change!
    }

    @Test
    void synchronizedList_threadSafe() {
        List<String> syncList = Collections.synchronizedList(new ArrayList<>());
        syncList.add("TXN-001");
        syncList.add("TXN-002");

        assertThat(syncList).hasSize(2);
        // All individual operations are synchronized.
        // BUT: iteration needs external sync!
    }

    @Test
    void factoryMethods_emptyAndSingleton() {
        List<Object> empty = Collections.emptyList();
        assertThat(empty).isEmpty();
        assertThatThrownBy(() -> empty.add("X"))
            .isInstanceOf(UnsupportedOperationException.class);

        List<String> single = Collections.singletonList("SAV2001");
        assertThat(single).containsExactly("SAV2001");

        List<String> fiveCopies = Collections.nCopies(5, "DEFAULT");
        assertThat(fiveCopies).hasSize(5);
        assertThat(fiveCopies).allMatch("DEFAULT"::equals);
    }
}
